"""Authored, source-grounded narration and illustrated states for the full companion."""
import json
import re
from pathlib import Path

ROOT=Path(__file__).resolve().parents[3]
HERE=Path(__file__).parent
chapters=[]

def chapter(slug,title,purpose,figure,sections):
    c={"id":f"{len(chapters)+1:02}-{slug}","title":title,"purpose":purpose,"figure":figure,"source_sections":sections,"beats":[]}
    chapters.append(c);return c
def beat(c,title,text,cards,*,layout="flow",status="Current implementation",note="",key=None):
    c['beats'].append({"id":key or f"{c['id']}-{len(c['beats'])+1:02}","title":title,"text":text,"cards":cards,"layout":layout,"status":status,"note":note})
def intro(c,text):
    beat(c,c['title'],text,[],layout="intro",note=c['purpose'])
def card(title,*lines,icon="receipt"):return {"title":title,"lines":list(lines),"icon":icon}

c=chapter('purpose','The problem and the product','Find repositories by their purpose and relationships, then keep your decisions.',1,[1,2])
intro(c,"Section one. The problem and the product. GitHub Manager helps you discover, understand, and organize repositories. The purpose is to turn a scattered collection into a workspace whose relationships you can inspect and change.")
beat(c,'A list does not explain the relationships',"Imagine starting an API project. You have your own services, shared repositories, and libraries starred for later. Names and programming languages help you search. They do not explain which pieces support the same initiative. Two Python repositories may serve entirely different purposes.",[card('Your collection','Owned repositories','Shared work','Starred libraries',icon='folder'),card('The missing question','What does it do?','Which initiative?','What supports that claim?',icon='search'),card('A useful workspace','Browse and filter','Inspect relationships','Keep manual control',icon='check')])
beat(c,'Source facts and organization have owners',"GitHub remains the source of repository facts: identity, links, visibility, and available metadata. The application builds selected evidence locally. AI proposes an organization, and the user reviews it. This separation matters because a convenient suggestion must not quietly replace a fact or a deliberate decision.",[card('GitHub facts','Identity and URL','Visibility and metadata',icon='globe'),card('Local evidence','Purpose excerpts','Phrases and provenance',icon='receipt'),card('Your organization','Accept, edit, reject','Manual decisions persist',icon='check')])
beat(c,'Follow one example through the system',"We will follow Orion, an authored synthetic patient-intake application. Its displayed classification comes from a saved real API test. We will also use a public FastAPI library as a contrast. These examples explain the mechanics; they are not a new account recording or a new benchmark.",[card('Orion application','Synthetic fixture','Saved real API answer',icon='code'),card('FastAPI library','Public reference sample','Different product role',icon='code'),card('The story','Evidence → possibilities','Request → review → memory',icon='receipt')],status='Historical examples',note='Synthetic input and saved provider output; no fresh repository inference')

c=chapter('vocabulary','Organization vocabulary','Give initiative, subject and technology different meanings.',1,[1])
intro(c,"Section two. Organization vocabulary. Before classification, we need to define what a relationship means. The purpose is to keep an initiative, a capability, and a technology from becoming one confusing pile of labels.")
beat(c,'Four questions, four concept types',"A Project answers which product or initiative a repository supports. A Domain groups those Projects into a broader area. A Topic describes a primary capability or subject. A Tag describes technology or another useful characteristic. For Orion, the examples are the clinical platform, Healthcare, Web APIs, and Python.",[card('Domain → Project','Healthcare','Orion Clinical Platform',icon='folder'),card('Topic','Web APIs','Primary capability',icon='globe'),card('Tags','Python · FastAPI','Implementation technology',icon='tag')],note='Healthcare is the separately approved benchmark registry parent')
beat(c,'Relationships are not exclusive folders',"A repository may support more than one Project. Its Domains derive through those Project memberships; the classifier does not assign Domains independently. Topics and Tags remain useful when no Project applies. The application's Topics are separate from the native topics supplied by GitHub.",[card('Repository','Can support two Projects','Many-to-many relationships',icon='code'),card('Projects → Domains','Derived parent groups','No independent Domain label',icon='folder'),card('Independent dimensions','Topics and Tags remain','GitHub topics stay distinct',icon='tag')])
beat(c,'Sharing a framework is not sharing an initiative',"The Orion application uses FastAPI and Python. The FastAPI library is itself a reusable framework. Sharing those words does not make the library part of Orion. Under the primary-label policy, incidental capabilities are omitted, and a library's own name is not automatically its dependency Tag. Next, we decide what evidence can support that distinction.",[card('Orion application','Belongs to Orion','Uses FastAPI and Python',icon='code'),card('Shared technology','Useful similarity','Not initiative identity',icon='search'),card('FastAPI library','Web APIs · Python','No Orion membership',icon='code')],layout='compare',status='Historical examples')

c=chapter('context','Context engineering','Select, authorize and structure the information needed for a decision.',1,[2,3,4])
intro(c,"Section three. Context engineering. Its purpose is to choose what information the model sees, what that information means, and which boundaries remain outside the model. A longer prompt is not automatically a better decision.")
beat(c,'Four kinds of context have different authority',"We separate trusted source facts, untrusted repository prose, user-owned organization, and execution identity. Canonical IDs, rejections, revisions, and evidence hashes constrain the operation. The application does not send every stored record to the model. For example, protected decisions filter candidates before prompting rather than becoming an entire conversation history.",[card('Source context','GitHub facts','README treated as data',icon='receipt'),card('User context','Approved IDs and rules','Manual choices and rejections',icon='check'),card('Execution context','Workspace and revisions','Profile hash and policy',icon='lock')])
beat(c,'Privacy is a gate before counting',"Hosted input is restricted to verified public repositories and synthetic fixtures in this implementation. Private or unknown visibility fails closed, including phrases derived from private text. Local rules can still help organization. Narrow cleaning patterns are hygiene, not a complete secret scanner or prompt-injection defense. The model has no tools with which to act on README instructions.",[card('Verified public / synthetic','Policy check before count','Eligible bounded input',icon='check'),card('Private / unknown','Hosted input excluded','Local rules still possible',icon='lock'),card('Defense in layers','Limited cleaning','No model tools','Application validation',icon='receipt')],layout='compare')
beat(c,'Runtime context is different from development context',"The working runtime is local Next.js, FastAPI, and SQLite. LangChain connects structured requests; it does not own the application's memory. During development, user decisions outrank approved design, plans, and historical discussion. Phase zero checked access; phase zero point five checked AI readiness; phase zero point nine delivered the local app. Cloud runtime remains deferred.",[card('Local runtime','Next.js → FastAPI','SQLite application state',icon='code'),card('Development context','Latest user decision first','Approved design and plan','History explains tradeoffs',icon='receipt'),card('Readiness history','Access → AI → local app','Preserved reports','AWS runtime deferred',icon='folder')],note='Stored app state is not model conversational memory')

c=chapter('evidence','Evidence and chunking','Preserve source-linked purpose text while keeping the request bounded.',3,[5])
intro(c,"Section four. Evidence and chunking. The purpose is to preserve the sentence that explains a repository, while excluding material that is unlikely to help organization. We begin with a README, not an AI-generated summary.")
beat(c,'Select purpose blocks, retain their source',"The extractor parses Markdown blocks and applies heading-based selection. Metadata becomes evidence zero; selected README text receives additional IDs. For Orion, evidence one says: patient intake API for the Orion Clinical Platform. Uses FastAPI and Python. The language metadata is empty, so Python is supported by prose rather than an invented GitHub value.",[card('README Overview','Patient intake API for the','Orion Clinical Platform.','Uses FastAPI and Python.',icon='receipt'),card('E0 · metadata','Name and description','Topics and language','Language value: unknown',icon='receipt'),card('E1 · purpose','Original selected sentence','Source-linked evidence ID',icon='check')],layout='evidence',status='Historical fixture')
beat(c,'Bytes, characters and tokens are different bounds',"The input byte ceiling limits the fetched document. Selected blocks and total evidence have character bounds. The compact classification profile then keeps metadata, up to two README records, and up to eight phrase strings. Exact request tokens are counted later. Hashes bind the selected content and configuration. Offsets identify cleaned text, not original README line numbers.",[card('Document / evidence bounds','262,144 input bytes','700 characters per block','8,000 selected characters',icon='receipt'),card('Compact profile','Metadata: ≤600 characters','≤2 README records','≤8 phrase strings',icon='folder'),card('Provenance','SHA-256 content/config','Offsets in cleaned evidence','Exact tokens counted later',icon='lock')])
beat(c,'A simple selector has visible weaknesses',"Heading rules are inspectable and avoid a hosted summarization pass, but can cut sentences or crowd out better evidence. Format noise, late negation, and multilingual headings need tests. The app received a separately versioned cleanup wrapper; frozen benchmark profiles stayed unchanged. Retrieval can see full selected evidence that compact generation omits, so both stages need their own checks.",[card('Useful simplicity','Local extraction','Direct source path','No summary-model call',icon='check'),card('Failure modes','Truncated sentence','Wrong early passage','Negation or language loss',icon='search'),card('Improve carefully','Version cleanup separately','Preserve frozen evidence','Measure passage inclusion',icon='receipt')],note='Complete-sentence and candidate-conditioned packing remain proposed improvements')

c=chapter('keywords','Local algorithms','Extract useful signals without confusing keyword scores with meaning.',3,[6,14])
intro(c,"Section five. Local algorithms. Their purpose is to expose compact signals before an expensive decision. We use phrase extraction and corpus counts, but those numbers do not establish initiative membership or semantic understanding.")
beat(c,'RAKE turns selected text into ranked phrases',"RAKE splits around stopwords and punctuation. Word frequency and co-occurrence contribute to phrase scores. Our configuration considers one to four words, retains up to twenty candidates, normalizes duplicates, and checks source spans. In Orion, patient intake API and Orion clinical platform each score nine. FastAPI and Python score one. Those are weights, not probabilities.",[card('Selected text','Purpose sentence','Local stopword splitting',icon='receipt'),card('RAKE score','Σ degree(word) / frequency(word)','1–4 words per phrase','Top 20 before span checks',icon='search'),card('Retained signals','patient intake api · 9','orion clinical platform · 9','fastapi · 1 · python · 1',icon='tag')],layout='keywords',status='Historical fixture and implemented algorithm')
beat(c,'YAKE and corpus frequency answer other questions',"YAKE was compared offline using local document features such as position, capitalization, and frequency. It is not the production extractor. Its measured runtime included repeated process startup, so the ratio is not an intrinsic speed comparison. Corpus document frequency counts a term once per repository. That pretest table is different from the concept-document IDF used in retrieval.",[card('YAKE · compared offline','English configuration','Local document features','No production adoption',icon='search'),card('Repository frequency','Once per repository','Repeated words do not add','Not semantic clustering',icon='folder'),card('Concept-document IDF','Different searchable corpus','Used by candidate retrieval','Do not mix denominators',icon='receipt')],status='Offline comparison / current baseline')
beat(c,'Keywords help matching but can add noise',"A bag of phrases loses relationships, including the word not. Purpose prose must survive. In one historical FastAPI ablation, adding RAKE phrases used more input tokens without changing the unwanted secondary labels. That single case proves neither that phrases always help nor that they are unnecessary. The product also has no learned project-clustering engine or automatically learned rules.",[card('Keep prose','Preserve purpose and negation','Keywords are supplementary',icon='receipt'),card('One-case ablation','988 tokens with RAKE','932 without phrases','Same reported assignments',icon='search'),card('Limits of the evidence','No broad quality gain shown','No learned clustering','No automatic rule induction',icon='lock')],status='Historical limited experiment')

c=chapter('taxonomy','Taxonomy intelligence','Propose a useful collection vocabulary, then publish only reviewed concepts.',2,[10])
intro(c,"Section six. Taxonomy intelligence. The purpose is to propose a vocabulary for a collection. This is different from assigning labels to one repository. Discovery can suggest new concepts; classification must use concepts already approved.")
beat(c,'Collection context reveals connected initiatives',"The saved discovery request contained thirty compact profiles: ten public samples and twenty authored fixtures. Orion's API, UI, booking, and audit records supplied related purpose evidence. The model proposed Orion Clinical Platform with a Clinical Operations parent and supporting repository IDs. Its twenty proposals were a draft, not a published organization.",[card('Collection evidence','30 compact profiles','10 public · 20 synthetic','Related Orion services',icon='folder'),card('Proposed vocabulary','Orion Clinical Platform','Parent: Clinical Operations','Supporting repository IDs',icon='code'),card('Review before publication','Edit names and definitions','Inspect aliases and parents','Approve useful concepts',icon='check')],status='Historical taxonomy test',note='The classification benchmark registry was separately authored and approved')
beat(c,'Sampling and packing preserve a bounded collection',"The app samples owner and language buckets using a deterministic round-robin approach. Collection packing uses a conservative byte allowance before exact token counting, shortening records and pruning phrases where necessary. This can miss structure outside the cohort. The saved direct collection request used its original packing path, so its token counts cannot be attributed to a later optimization.",[card('Choose a cohort','Owner/language buckets','Round-robin coverage','A sample, not every repo',icon='folder'),card('Pack bounded context','Prune phrases / shorten','Conservative byte allowance','Then exact request count',icon='receipt'),card('Preserve interpretation','Small cohort can miss links','Original test stays frozen','No broad compression curve',icon='search')])
beat(c,'Reserved terms can hide in aliases and archives',"Publication normalizes names and aliases, including Unicode handling, and checks reservations. A visible name can conflict with an alias or archived concept. The app exposes the conflicting record and offers opt-in reuse, renaming, removal, or exclusion. These deterministic checks protect canonical consistency. Similar language is not permission for an automatic semantic merge.",[card('Proposed term','Name or alias','Normalized comparison',icon='tag'),card('Reservation registry','Active canonical names','Aliases and archived terms','Inspect the matching record',icon='search'),card('User remediation','Reuse · rename · remove','Explicit review and undo','No automatic semantic merge',icon='check')],layout='state')

c=chapter('retrieval','Retrieval','Find plausible approved concepts before deciding which relationships hold.',2,[3,7])
intro(c,"Section seven. Retrieval. Its purpose is to find plausible concepts from the approved vocabulary. The repository evidence is the query; concept names, definitions, and aliases are the searchable documents. A shortlist is not a decision.")
beat(c,'Sparse scoring exposes why a candidate surfaced',"The method called TF-IDF in the code is actually binary-IDF cosine. It weights less common registry terms and normalizes overlap, while repeated terms do not increase frequency. A name or alias whose tokens all appear adds three once. Token order and positive assertion are not required. Positive candidates are ranked by kind, with stable-ID ties and bounded limits.",[card('Binary-IDF cosine','Presence, not repeated counts','Rare terms weighted more','Normalized lexical overlap',icon='search'),card('Alias boost','All normalized tokens present','Add 3 once','No word-order assertion',icon='tag'),card('Bound by kind','8 Projects · 10 Topics','12 Tags · positive scores','Domains excluded',icon='folder')])
beat(c,'Follow the actual six-candidate Orion shortlist',"Orion retrieves its own Project, Web APIs, FastAPI, and Python. Forge also surfaces through platform, and Package Management through Python. The strong Orion score includes the alias boost. These are ranking scores, not membership probabilities. The next stage must distinguish actual purpose evidence from distracting shared words.",[card('Projects','Orion · 3.738168','Forge · 0.111179',icon='folder'),card('Topics','Web APIs · 3.119897','Package Management · 0.119067',icon='globe'),card('Tags','FastAPI · 3.244630','Python · 3.157589',icon='tag')],layout='retrieval',status='Recomputed historical shortlist')
beat(c,'BM25 was a comparison, not a hidden extra layer',"BM25 was compared offline with the same alias boost and candidate caps. It adds saturated term frequency and document-length normalization. On the small reused comparison, both lexical methods covered the expected evaluation labels; alias-only missed four Topics. That supports feasibility, not sparse superiority over dense search. There is no embedding query, neural reranker, or autonomous retrieval agent in the current product.",[card('Selected baseline','Binary-IDF cosine','Inspect term matches','Simple deterministic retrieval',icon='search'),card('BM25 · compared offline','Saturated term frequency','Length normalization','Same task-specific boost',icon='receipt'),card('Interpretation','Small registry / broad caps','No dense comparison result','No active neural reranker',icon='lock')],status='Current baseline / offline alternatives')

c=chapter('augmentation','Augmentation','Assemble evidence, candidate meaning and decision policy into the model request.',2,[4,8])
intro(c,"Section eight. Augmentation. The purpose is to assemble a decision-ready request from the evidence and retrieved possibilities. Retrieval supplies options. Augmentation explains those options and the rules for selecting them.")
beat(c,'The repository supplies evidence, not the answer key',"For Orion, the payload includes repository identity, public or synthetic source status, revision, evidence hash, selected evidence, phrase strings, and candidate records. Evidence one preserves the patient-intake sentence. Candidate records contain canonical ID, kind, name, and description. Aliases helped retrieval but are not serialized into those candidate objects. Expected evaluation labels are never supplied.",[card('Repository context','E0 metadata + E1 purpose','Phrases and provenance','Revision / policy / hash',icon='receipt'),card('Candidate definitions','ID · kind · name','Short description','Aliases used in retrieval only',icon='folder'),card('No answer key','Reference labels excluded','Candidate ≠ assignment','Evidence must justify choice',icon='lock')],layout='request')
beat(c,'Policy makes the semantic task explicit',"The system instructions require supported approved IDs, primary-purpose Topics, and primary implementation Tags. Shared frameworks do not prove initiative membership. Negation matters; multiple Projects are allowed. Unsupported input can produce no match or a request for more context. User decisions remain application constraints rather than an invitation for the model to overrule them.",[card('Decision rules','Primary purpose / technology','Respect explicit negation','Multiple Projects allowed',icon='check'),card('Allowed outcomes','CLASSIFIED','NO_MATCH','NEEDS_MORE_CONTEXT',icon='receipt'),card('User authority','Protected rejections filtered','Manual decisions prevail','No invented canonical IDs',icon='lock')],layout='request')
beat(c,'Count the assembled contract, not just the prose',"A strict response schema describes assignments, evidence references, reasons, status, and summary. LangChain binds that schema to the hosted request. The harness inspects the assembled messages and schema before counting input tokens. This is retrieval-augmented structured classification, with durable application memory. It is not a conversational document-question-answering agent, and adaptive budgets do not turn it into Adaptive RAG.",[card('Prompt envelope','Evidence + candidates','Instructions + JSON Schema',icon='receipt'),card('LangChain integration','Transport and schema binding','Not application memory','No autonomous tools',icon='code'),card('Exact contract count','Messages + schema overhead','Reserve before generation','Bounded structured output',icon='lock')],layout='request')

c=chapter('generation','Generation and validation','Return supported IDs, then check whether a proposal is safe and useful.',2,[8,15])
intro(c,"Section nine. Generation and validation. The purpose is to turn the assembled context into a bounded proposal, then check it before it affects organization. Valid JSON is only the beginning of that check.")
beat(c,'The saved model answer chose four supported IDs',"In the preserved Orion call, the model selected Orion Clinical Platform, Web APIs, FastAPI, and Python. All four assignments cited evidence one. Forge and Package Management were omitted. The request counted seven hundred sixty input tokens and returned one hundred ninety-five output tokens. This visible result does not expose the model's private reasoning process.",[card('Saved request','760 counted input tokens','Evidence + six candidates',icon='receipt'),card('Returned proposal','Orion · Web APIs','FastAPI · Python','All cite E1',icon='check'),card('Not selected','Forge Build Platform','Package Management','195 output tokens',icon='folder')],layout='selection',status='Saved real API result from synthetic fixture')
beat(c,'Application checks go beyond a response schema',"Validation checks active IDs, kinds, workspace ownership, allowed candidates, duplicates, field limits, status, and evidence references. Dispatch and commit also check access, profile hashes, revisions, and user decisions. Suggestions remain proposals until accepted. A real evidence ID may still cite irrelevant prose, and the model's confidence is not a calibrated accuracy probability.",[card('Structural validity','Known active ID / kind','Allowed workspace/candidate','Duplicates and field bounds',icon='lock'),card('Current state','Access and profile hash','Revision / decision checks','Reject stale application writes',icon='receipt'),card('Semantic review','Does the passage support it?','Confidence is uncalibrated','User accepts useful proposals',icon='check')])
beat(c,'Model roles and audit gaps need honest labels',"Luna is the task default supported by the limited classification tests; Sol supplied the taxonomy draft. A comprehensive model-winner study was not completed. The audit also found evidence-ID validation broader than the transmitted compact set, and a taxonomy prompt limit of twenty versus a validator limit of fifty. Those are improvement tasks, not shipped guarantees.",[card('Task defaults','Luna: classification','Sol: vocabulary discovery','Limited feasibility evidence',icon='code'),card('Documented parity gaps','Full-profile ID allowance','20 requested / 50 validated','Needs tighter transmitted set',icon='search'),card('What remains uncertain','No exhaustive winner study','No confidence calibration','No guaranteed entailment',icon='receipt')],status='Historical model checks / documented current gaps')

c=chapter('counterexamples','Counterexamples and failure cases','Use awkward inputs to distinguish matching words from supported meaning.',3,[8,16,17])
intro(c,"Section ten. Counterexamples and failure cases. Their purpose is to show where an apparently sensible pipeline can mislead us. We keep the confusing evidence visible rather than explaining only the clean success case.")
beat(c,'Negation and multiple memberships change the answer',"One fixture explicitly says it is not part of Helios or Orion. Lexical names still retrieve both Projects, but the saved classifier selects HTTP Clients and Python with neither Project. Another audit fixture genuinely supports two initiatives. The task must allow both. A forced single winner would change the meaning of organization.",[card('Negated API fixture','Not part of Helios or Orion','Names still retrieve strongly','No Project selected',icon='receipt'),card('Orion audit fixture','Supports two initiatives','Two Project relationships','Multi-label semantics',icon='folder'),card('Required distinction','Word presence ≠ assertion','Do not force one winner','Retain purpose prose',icon='search')],status='Historical authored fixtures')
beat(c,'FastAPI exposed a packing and policy weakness',"The full FastAPI profile contains its purpose statement, but an uppercase title marker let documentation links occupy compact slots. Retrieval could see evidence the generator did not receive. Metadata still supported the saved answer, Web APIs and Python. An earlier answer added unwanted secondary labels. Primary-only policy clarified the task, but reused cases cannot establish an independent causal improvement.",[card('Full selected profile','Purpose passage available','Retrieval can use it',icon='receipt'),card('Compact model context','Early links occupy slots','Metadata supplies support','Packing weakness remains',icon='search'),card('Primary-label correction','Web APIs · Python','Secondary labels omitted','Reused-case qualification',icon='check')],status='Observed historical examples and current audit gap')
beat(c,'Sparse or adversarial input needs an honest exit',"Empty, fork-only, and metadata-only cases need no-match or uncertainty paths. Installation noise can introduce unrelated names. English extraction can miss other languages. Narrow cleaning can miss malicious instructions or secret-like text. These fixtures explore boundaries; they are not a comprehensive security benchmark. Next, we preserve the decisions and uncertainty that follow from these cases.",[card('Sparse evidence','Metadata fallback','NO_MATCH or uncertainty','No forced classification',icon='receipt'),card('Misleading content','Install examples / negation','Multilingual headings','Instruction-like text',icon='search'),card('Residual risk','Incomplete cleaning/scanning','No comprehensive attack study','Preserve honest outcomes',icon='lock')])

c=chapter('memory','Memory and user authority','Preserve completed work and corrections independently of current labels.',4,[11,12])
intro(c,"Section eleven. Memory and user authority. The purpose is to preserve useful state across changes. Here, memory means application records, not a model remembering a conversation or a LangChain conversation-memory component.")
beat(c,'Keep four dimensions separate',"Relationships, completed analysis, freshness, and review status answer different questions. A successful no-match is completed analysis. Removing Orion's Project can leave its Topic and Tags useful, while the receipt remains. Provider replay cache and optional run history are different records. Deleting one display or membership does not silently make the repository eligible for another paid decision.",[card('Current organization','Projects / Topics / Tags','May change or be removed',icon='folder'),card('Analysis receipt','Completed work persists','NO_MATCH is complete','Separate from replay/history',icon='receipt'),card('Freshness and review','Evidence can become stale','Suggestions need decisions','Stale ≠ paid permission',icon='check')],layout='receipt')
beat(c,'Corrections must survive later organization',"Accepting a proposal creates a user decision. Rejecting or removing a relationship leaves a protected tombstone. Approved rules can supply deterministic mappings, subject to those rejections. Ordinary organization cannot recreate a rejected edge behind the user's back. These protections preserve authority; they do not prove every accepted relationship was independently verified truth.",[card('Accept / reject / remove','USER authority','Protected rejection record',icon='check'),card('Approved local rules','Explicit reusable decisions','Respect protected rejections','No automatic rule learning',icon='receipt'),card('Later organization','Reuse compatible state','Do not restore rejected edge','Acceptance ≠ research gold',icon='lock')],layout='state')
beat(c,'Reconcile known information without fresh inference',"Local reconciliation applies approved rules, compatible stored assignments, or contiguous name and alias matches for review. This match is stricter than retrieval's unordered alias tokens. Local suggestions have visible provenance and zero model confidence. They do not manufacture AI completion. Fresh analysis remains available with an explicit reason and reviewed budget when the user wants a new judgment.",[card('Local reconciliation','Approved rules','Compatible stored answers','Contiguous alias matches',icon='search'),card('Honest provenance','RULE / stored / LOCAL_MATCH','Reviewable proposals','No new AI completion',icon='receipt'),card('Deliberate refresh','Choose taxonomy/classification','State reason and review bound','Privacy/authority still apply',icon='check')])

c=chapter('loops','Loop engineering','Control when work runs, skips, reconciles, retries or becomes stale.',4,[12])
intro(c,"Section twelve. Loop engineering. Its purpose is to control transitions around inference. We need to know when to run, when to skip, and when a result has become unsafe to apply. This is application control, not an autonomous model thought-and-action loop.")
beat(c,'Admit one attempt and preserve uncertain outcomes',"Preview and worker check admission before constructing the provider or making a count request. Transactions claim running attempts so concurrent starts do not independently process the same operation. Previously attempted or uncertain work requires deliberate review, not a silent retry. Explicit re-analysis can bypass memoization while retaining privacy, schema, and spending checks.",[card('Admission first','New eligible operation?','Prior / uncertain receipt?','Before provider construction',icon='lock'),card('Transactional claim','One RUNNING attempt','Idempotent plan start','No duplicate concurrent work',icon='receipt'),card('Explicit fresh analysis','Separate operation choice','Reason and reviewed budget','Access checks still enforced',icon='check')],layout='state')
beat(c,'Thresholds schedule work, not permission',"Automatic organization accumulates eligible changes. Defaults combine weight six and three distinct entities, or two new Projects, followed by a ninety-second quiet period and a thirty-minute cooldown. Types and thresholds are configurable. Consumed event sequences prevent endless rescheduling. Existing analysis still reconciles locally. A change upstream cannot be noticed before its content is fetched.",[card('Accumulate eligible changes','Weight ≥6 AND entities ≥3','OR new Projects ≥2','Default window: 15 minutes',icon='receipt'),card('Wait before scheduling','Quiet: 90 seconds','Cooldown: 30 minutes','Consume event sequence',icon='clock'),card('Apply admission again','New eligible work may use AI','Prior analysis works locally','No automatic paid resend',icon='lock')],layout='timeline',note='Create, Create Project, Edit, Archive, Merge, Rule and Evidence are configurable event types')
beat(c,'Fences protect a newer decision from an older result',"Revision, generation, policy, and epoch fences bind a response to current state. If the user edits or resets during generation, unsafe associations are discarded while historical cost and processing evidence remain. Reset uses a scoped, expiring, one-use preview and exact confirmation. It preserves cost history and readiness reports. These are tested local safeguards, not distributed exactly-once execution or forensic erasure.",[card('Request starts','Bind profile / decisions','Generation and epoch fence',icon='receipt'),card('User changes state','Edit, reject or reset','Advance relevant fence',icon='check'),card('Old response arrives','Discard unsafe assignments','Keep historical processing','Keep cost reservations',icon='lock')],layout='timeline')

c=chapter('harness','Harness engineering','Make every admitted request measurable, authorized and finite.',5,[13])
intro(c,"Section thirteen. Harness engineering. Its purpose is to make a model request measurable and bounded before it leaves the application. A successful connection alone tells us nothing about decision quality, safe state changes, or total cost.")
beat(c,'Inspect, count, reserve, then generate',"The provider inspects the serialized LangChain request, including destination, model, instructions, schema, output limits, and disabled tool or conversation fields. The HTTP hook checks current session and workspace authorization. Counting consumes an HTTP attempt. Only a successful bounded count permits a monetary reservation and generation. SDK retries are disabled to prevent hidden request multiplication.",[card('Inspect / authorize','Allowed endpoint and model','Current session / workspace','No tools or hidden state',icon='lock'),card('Exact input count','Messages + schema overhead','Consumes an HTTP attempt','Block if count unavailable',icon='receipt'),card('Reserve / generate','Conservative maximum','Finite generations / HTTP','SDK retries: zero',icon='code')],layout='budget')
beat(c,'An absent response does not mean an absent charge',"Known valid usage settles the estimate. Refusal or incomplete output is not a successful replay entry, but can still cost tokens. Missing usage, timeout, and uncertain failures keep the maximum reservation. A bound violation stops later paid admission. Selected provider rejections have a specific local accounting policy; none of these estimates is independent invoice reconciliation.",[card('Known completed usage','Settle estimated cost','Validate before replay cache',icon='check'),card('Refused / incomplete','Not a successful cache entry','Generation may still cost',icon='receipt'),card('Unknown / over bound','Keep reservation if uncertain','Stop on bound violation','No automatic retry',icon='lock')],layout='budget')
beat(c,'Fixed windows and adaptive grants share a ceiling',"Fixed mode has audited request and generation limits. Selective renewal or override preserves past attempts and spending. Adaptive mode admits a finite reviewed dollar grant under the same cumulative cap. Per-call reservations transfer from a run hold without double counting. Recovery links holds to jobs, releases unused terminal money, and preserves unknown-call holds. Separate local databases still require reconciliation.",[card('Fixed mode','HTTP window / generations','Explicit selective override','Past attempts remain',icon='receipt'),card('Adaptive mode','Finite run-dollar grant','Finite HTTP and generations','Shared cumulative ceiling',icon='lock'),card('Hold / job recovery','Transfer, not double count','Release unused run money','Keep uncertain call reserve',icon='check')],layout='budget',note='Local reconciliation protocol; not a cross-database atomic transaction')

c=chapter('tokenomics','Tokenomics and optimization','Measure the total useful outcome, not merely a smaller prompt.',5,[14])
intro(c,"Section fourteen. Tokenomics and optimization. The purpose is to understand what each decision consumes and which costs can be avoided. We separate historical estimates, conservative admission bounds, and the broader cost of a useful accepted relationship.")
beat(c,'A reservation is a bound, not typical usage',"The harness pins a rate snapshot and counts assembled input. It reserves possible output, a conservative cache-write allowance, and headroom without assuming a cache discount. Known usage later settles in integer microdollars. Reasoning tokens already belong to output and must not be added twice. A maximum-output reservation is not a prediction of the answer's usual length.",[card('Before generation','Counted assembled input','Possible output maximum','Cache-write allowance + 5%',icon='lock'),card('Known usage settlement','Input / cached / write / output','Round to integer microdollars','Reasoning already in output',icon='receipt'),card('Correct interpretation','Bound ≠ typical usage','Estimate ≠ invoice','Pinned historical rates',icon='check')],layout='budget')
beat(c,'Historical counts need the right denominator',"The twenty-case API round made twenty generation requests and twenty input-count requests: forty provider HTTP operations. It recorded sixteen thousand forty-one input tokens and three thousand four hundred fourteen output tokens. The rounded inference estimate was about three-tenths of a cent. This excludes media, infrastructure, indexing, and human review; it is not a production cost guarantee.",[card('Historical round','20 generations + 20 counts','40 total provider HTTP','20 reused evaluation cases',icon='receipt'),card('Recorded usage','16,041 input tokens','3,414 output; 702 reasoning','Reasoning not added again',icon='code'),card('Historical estimate','$0.003319 inference only','Not accepted-decision cost','Not an invoice guarantee',icon='check')],status='Historical October 13 rate snapshot / frozen experiment')
beat(c,'Avoiding work is different from provider caching',"Compact evidence, candidate caps, and bounded collection sampling reduce individual requests, but can omit useful context. Receipts and local reconciliation can avoid another request entirely. Provider prompt caching still invokes a model, and no discount benefit appeared in that round. Count latency, evidence refresh, storage, and reviewer corrections also matter. Optimize cost per correct, accepted, current association.",[card('Reduce request size','Selected evidence / phrases','Per-kind candidate caps','Cohort sampling tradeoffs',icon='search'),card('Avoid a new decision','Durable receipts / NO_MATCH','Local rules and reconciliation','Different from prompt cache',icon='receipt'),card('Total useful outcome','Source / index / runtime cost','Latency and reviewer effort','Correct + accepted + current',icon='check')],layout='budget')

c=chapter('evaluation','Evaluation and evidence','Evaluate retrieval, decisions and workflow separately, with honest limits.',6,[15,19])
intro(c,"Section fifteen. Evaluation and evidence. The purpose is to learn which stage succeeds, which stage fails, and how far the measurements generalize. A single attractive score cannot answer all three questions.")
beat(c,'Know what the small benchmark actually contains',"The frozen corpus has thirty repositories. Ten were development cases; twenty formed the evaluation partition, with eight public libraries and twelve synthetic cases. The registry has forty-two concepts, including four non-searchable Domains. Public labels were proposed and user-approved. Related initiatives were grouped, but policy clarification reused evaluation cases. The final round is regression validation, not untouched generalization evidence.",[card('Corpus and partitions','30 total: 10 development','20 evaluation: 8 public','12 authored synthetic',icon='folder'),card('Vocabulary and references','42 concepts / 38 searchable','Public labels user-approved','Synthetic fixture truth',icon='receipt'),card('Important qualification','Small Python-heavy collection','Primary-label policy tuned','Final set reused',icon='lock')],status='Frozen historical evaluation')
beat(c,'Retrieval recall and assignment quality are different',"Candidate recall asks whether expected IDs reached the shortlist. Both lexical methods covered all expected evaluation labels under generous caps. Classification then produced fifty true positives, zero false positives, and two misses: micro F one of ninety-eight percent. Both missing labels had been retrieved, locating those errors after candidate inclusion, without proving whether packing or model selection caused them.",[card('Candidate retrieval','52 expected IDs reached','Binary cosine and BM25','Broad caps / small registry',icon='search'),card('Final assignments','TP 50 · FP 0 · FN 2','Precision 100% · recall 96.2%','Micro F1 98.0%',icon='check'),card('Locate, do not overclaim','Missed labels were retrieved','Telemetry / Python misses','Packing vs model not isolated',icon='receipt')],layout='metrics',status='Historical reused twenty-case results')
beat(c,'Quality, support and calibration need more evidence',"Taxonomy drafts passed structural checks and received qualitative acceptance, but no numeric human rubric was recorded. One repeated classification agreed; that is not long-run stability. Limited timing, contract, race, privacy, and recovery checks establish specific behaviors. They do not measure citation entailment or calibrated confidence. No complete RAGAS-style question-answering evaluation or independent production accuracy study was performed.",[card('Established checks','Structural taxonomy validity','Qualitative human review','Limited stability / timing',icon='check'),card('Harness and workflow','Admission / privacy / races','User precedence / restart','Historical checks, not rerun',icon='lock'),card('Missing evaluations','Evidence entailment rubric','Confidence calibration','Independent production study',icon='search')],layout='metrics')
beat(c,'Build the next evaluation before choosing another layer',"A stronger study needs independent annotations, unseen initiatives, harder neighbors, no-match cases, and broader languages. Freeze policy and source snapshots before comparing methods. Group related repositories when splitting, and report per-kind errors, abstention, source support, correction effort, and total cost. Confidence intervals and model-winner claims should follow adequate data rather than being manufactured from this small reused set.",[card('Independent references','Unseen initiatives / languages','Grouped train/test splits','Freeze policy and snapshots',icon='folder'),card('Measure each layer','Candidate + passage recall','Per-kind precision/recall','Abstention and source support',icon='search'),card('Measure workflow value','Human correction effort','Latency / total spending','Calibration and uncertainty',icon='check')],status='Proposed evaluation design')

c=chapter('future-retrieval','Stronger retrieval and contextual retrieval','Add a retrieval layer only when its errors and costs justify the change.',7,[9,17,18])
intro(c,"Section sixteen. Stronger retrieval and contextual retrieval. The purpose is to investigate specific weaknesses without mistaking architectural complexity for improvement. Everything in the research lane is a proposal or external reference, not a current product capability.")
beat(c,'Fix evidence selection before adding a new model',"First preserve complete sentences, decisive passages, and contradiction. Align evidence validation with exactly what was transmitted. Compare candidate-conditioned passage selection with today's simple packing at the same token ceiling. Sparse experiments can vary term frequency, field weights, alias order, boosts, and smaller caps. These tests ask which error is fixed, rather than assuming the next layer must be better.",[card('Repair evidence contract','Complete sentences / negation','Exact transmitted evidence IDs','Purpose passage inclusion',icon='receipt'),card('Sparse ablations','Count/sublinear TF-IDF / BM25','Field/phrase/alias scoring','Matched smaller caps',icon='search'),card('Equal-budget comparison','Decisive-passage recall','False Project association','Downstream quality and cost',icon='check')],status='Proposed experiments')
beat(c,'Dense and hybrid search need versioned units and filters',"A public-only bi-encoder trial could embed concept definitions and repository-purpose profiles separately. A small registry can use exact local similarity before an approximate-neighbor service. Cache by content and encoder version; preserve identity and access metadata. If dense search recovers real lexical misses, compare sparse and dense unions with reciprocal-rank fusion. A reranker adds cost and cannot recover a candidate absent from that union.",[card('Dense units','Concept definitions','Repository purpose / passages','Exact scoring before ANN',icon='search'),card('Version and authorize','Hash + encoder + preprocessing','Refresh only changed units','Access before retrieval/prompt',icon='lock'),card('Conditional added layers','Sparse+dense union → RRF','Cross-encoder if justified','Cannot recover omitted IDs',icon='code')],status='Proposed dense / hybrid / reranking experiments')
beat(c,'Contextual retrieval enriches indexed chunks',"Now, contextual retrieval. Its purpose is to make an indexed chunk meaningful beyond its isolated words. Anthropic's approach adds document-conditioned context before indexing chunks with embeddings and BM25, with optional reranking. Our deterministic metadata and purpose excerpts are not that mechanism. A trial could compare cheap metadata prefixes with generated context, accounting for indexing, refresh, privacy, and downstream support. External published results do not become measured GitHub Manager improvements merely by showing the reference diagram.",[card('Current context','Deterministic source metadata','Selected purpose excerpts','No generated chunk prefixes',icon='receipt'),card('External research pattern','Document-conditioned prefix','Embedding + BM25 indexing','Optional reranking',icon='search'),card('Proposed controlled trial','Metadata vs generated prefix','Index/update/privacy cost','Task-specific support metrics',icon='check')],status='External research / proposed comparison')
beat(c,'Bounded escalation is different from an autonomous agent',"A future controller could allow one extra source-linked evidence pass after an insufficient-context result, under a reviewed budget, then abstain. Adaptive RAG, Self-RAG, and corrective RAG are research references, not adopted implementations. Agentic retrieval would additionally need tool permissions and trajectory evaluation. Domain relationships alone do not create GraphRAG. Application memory does not make the model remember conversations.",[card('Bounded escalation','Meaningful new evidence','One reviewed extra pass','Abstain if still unsupported',icon='receipt'),card('Research comparisons','Adaptive-RAG / Self-RAG','CRAG / agent tool loops','Not currently implemented',icon='search'),card('Avoid misleading labels','No active dense hybrid RAG','No GraphRAG engine','Memory is application state',icon='lock')],status='Research comparison / proposed controller')

c=chapter('jev','Decision models: the Jev research question','Test bounded semantic judgments without changing multi-label meaning or user authority.',8,[18])
intro(c,"Section seventeen. Decision models, and the Jev research question. The purpose is to investigate whether a specialized decision interface could improve bounded judgments after the options are known. No Jev integration or live Jev test has been performed here.")
beat(c,'Ask support questions rather than forcing one winner',"TypeSafe describes Choice, Score, and Noul primitives for typed judgments. For repository organization, a candidate could be supported, unsupported, or unclear. Ask separately for each candidate when several memberships are possible. Open-ended taxonomy discovery still needs generation to propose new names and definitions. A choice among existing options cannot replace that creative vocabulary step.",[card('Typed judgments','Choice · Score · Noul','Known questions and options','State supplied explicitly',icon='code'),card('Preserve multi-label meaning','Judge each candidate','Allow uncertainty / no match','Two Projects can both fit',icon='check'),card('Keep discovery separate','Generate vocabulary drafts','Review names and aliases','Decisions follow known options',icon='folder')],status='External Jev interface / proposed application')
beat(c,'Confidence and provider changes need their own evaluation',"A probability-derived decision confidence is not the same as today's generated confidence number, and neither proves task calibration. A shadow study should retain the baseline, test negation and option order, and measure high-confidence errors, abstention, fallback, review effort, and total spending. Extra provider credentials, retention terms, retries, and failures require their own controls. Faster decisions do not guarantee better completed workflows.",[card('Evaluate uncertainty','Calibration / reliability','High-confidence errors','Selective risk vs coverage',icon='search'),card('Shadow comparison','Keep baseline outcomes','Negation and option order','Count fallbacks and cost',icon='receipt'),card('Provider implications','Credentials and data terms','Version / retry / unknown holds','Whole-workflow quality',icon='lock')],status='Proposed shadow evaluation')
beat(c,'Semantic judgment cannot grant operational authority',"Potential uses include candidate filtering, passage relevance, duplicate-review triage, or bounded assignment. Any filter can discard a correct candidate. Budget arithmetic, privacy policy, stable-ID validity, rejections, and stale-state protection stay deterministic. Adoption should require a measured quality-cost tradeoff on independent data, not a vendor headline. We finish by following the entire current workflow once more.",[card('Possible placements','Candidate / passage support','Review triage / assignment','Measure false filtering losses',icon='search'),card('Deterministic boundaries','Access and budget arithmetic','Canonical IDs / rejections','Current-state fences',icon='lock'),card('Promotion criterion','Independent quality evidence','Review and fallback burden','Useful outcome per total cost',icon='check')],status='Future research; no claimed adoption')

c=chapter('complete-trace','The complete trace and next steps','Reconnect each mechanism to the repository the user wanted to find.',8,[16,17,18,19,20])
intro(c,"Section eighteen. The complete trace and next steps. The purpose is to reconnect the technical layers to the original need: find useful repositories, understand why they belong together, and keep control as the collection changes.")
beat(c,'Trace one decision from source to reviewed state',"Orion's source sentence explains patient intake, the clinical initiative, FastAPI, and Python. Local extraction retains evidence one. Retrieval finds six possibilities. Augmentation supplies evidence, definitions, policy, and schema. Generation returns four supported IDs. Validation and review establish usable relationships. A receipt preserves completed work even if the user later removes a Project.",[card('Prepare and retrieve','Source → selected evidence','Approved vocabulary','Six possibilities',icon='receipt'),card('Request and decide','Evidence / policy / schema','Four returned IDs cite E1','Validate and review',icon='check'),card('Continue safely','Durable analysis receipt','Respect removed membership','Local reconcile / explicit fresh',icon='lock')],status='Saved example plus illustrative lifecycle')
beat(c,'Preserve evidence while improving the system',"Readiness phases, frozen corpora, source hashes, lockfiles, reports, and historical ledgers preserve what was actually tested. Reconstructing a request offline is not recovering an original wire log. This animation does not rerun application or model benchmarks. The original academic, illustrated, and publication editions remain available with exact inputs, formulas, qualifications, and references.",[card('Preserve the record','Phases 0 / 0.5 / 0.9','Corpus, hashes and lockfiles','Historical reports and ledgers',icon='folder'),card('Distinguish evidence','Observed provider answer','Offline reconstruction','Illustrative user action',icon='receipt'),card('Keep deeper references','Academic and illustrated texts','Publication v1 and v2','Full requests and formulas',icon='search')])
beat(c,'Improve the useful outcome, not just the architecture',"The next steps are better evidence packing, tighter validation parity, independent evaluation, and only then conditional retrieval or decision-model experiments. Cloud migration needs separate concurrency and recovery validation. The practical habit is simple: put the source, shortlist, request, answer, and resulting state beside one another. Change one user decision, follow the next run, and measure what improved.",[card('First improvements','Evidence contract / validation','Independent evaluation','Then optional model layers',icon='search'),card('Production gate','AWS runtime still deferred','Access / concurrency / recovery','Separate migration evaluation',icon='lock'),card('Return to the user','Find. Understand. Organize.','Corrections should last','You own the final decision',icon='check')],status='Current boundary / proposed next steps')

# Keep exact implementation details visible without turning narration into a table reading.
by_slug={c['id'][3:]:c for c in chapters}
by_slug['keywords']['beats'][2]['text'] += " The installed YAKE artifact's licensing also remained an adoption concern."
by_slug['keywords']['beats'][3]['cards'][0]['lines'].append('RAKE stoplist includes not / no')
by_slug['retrieval']['beats'][1]['cards'][0]['lines'].append('idf = log((1+N)/(1+df)) + 1')
by_slug['retrieval']['beats'][3]['cards'][1]['lines'].append('k1=1.5 · b=0.75 · epsilon=0.25')
by_slug['loops']['beats'][1]['text'] += " Classification cohorts use new-analysis, Project, and recency ordering, not a learned ranker."
by_slug['loops']['beats'][1]['cards'][0]['lines'].append('Cohort: new / Project / recency')
by_slug['tokenomics']['beats'][1]['note']='Task ceilings: classification 2,000 input / 2,048 output; taxonomy 12,000 input / 4,096 output. Historical pinned rates; no effort-level ablation.'
by_slug['evaluation']['beats'][1]['text'] += " Project-positive evidence is synthetic; private enterprise performance remains unestablished."
by_slug['evaluation']['beats'][3]['text'] += " Historical timings use nearest-rank percentiles from twenty observations, not a production guarantee. Subscription-based Codex checks were supplementary, not replacements for real API validation."
by_slug['evaluation']['beats'][3]['note']='Historical 4-client round: p50 2.974 s; p95 4.749 s. Different serial comparisons are not causal speed measurements.'
by_slug['future-retrieval']['beats'][2]['text'] += " Private embeddings are derived content and need separate permission."
by_slug['future-retrieval']['beats'][2]['note']='Proposed RRF: sum 1 / (k + rank). Tune cutoffs on development data; no current vector index or cross-encoder.'
by_slug['jev']['beats'][2]['note']='Example from the research note: 3 choices and top probability 0.6 gives normalized Choice confidence 0.4; not empirical calibration.'

def build():
    story={"date":"2026-10-15","title":"GitHub Manager — an illustrated AI system design","voice":"cedar","model":"gpt-4o-mini-tts","speed":.82,"target_spoken_wpm":[105,112],"fps":30,"width":1920,"height":1080,"max_http_requests":11,"combined_animation_request_cap":16,"combined_animation_media_cap_usd":2,"cumulative_ceiling_usd":5,"beat_lead_seconds":1,"beat_hold_seconds":3.5,"chapter_title_hold_seconds":4,"chapters":chapters}
    output=HERE/'story.json';output.write_text(json.dumps(story,indent=2)+'\n')
    marker='\n\nThat completes this part of the explanation.'
    beats=[b for c in chapters for b in c['beats']];takes=[];group=[]
    for b in beats:
        for sentence in re.split(r'(?<=[.!?])\s+',b['text']):
            trial=' '.join(x['text'] for x in group+[{'text':sentence}])+marker
            if len(trial)>3980 and group:takes.append(group);group=[]
            group.append({'beat':b['id'],'text':sentence})
    if group:takes.append(group)
    assert len(takes)<=7,(len(takes),sum(len(b['text']) for b in beats))
    (HERE/'takes.json').write_text(json.dumps([{'id':f'take-{i+1:02}','parts':g,'text':' '.join(p['text'] for p in g),'marker':marker.strip()} for i,g in enumerate(takes)],indent=2)+'\n')
    print(json.dumps({'chapters':len(chapters),'beats':len(beats),'words':sum(len(b['text'].split()) for b in beats),'characters':sum(len(b['text']) for b in beats),'tts_takes':len(takes),'maximum_take_characters':max(len(' '.join(b['text'] for b in g)+marker) for g in takes)},indent=2))
if __name__=='__main__':build()
